<script setup>
import { computed, ref, watch } from 'vue'
import { Head, Link, router, InfiniteScroll } from '@inertiajs/vue3'
import Maindashboard from '@/Layouts/Maindashboard.vue'
defineOptions({ layout: Maindashboard })
import VehiculoExternoFormModal from '@/Components/VehiculoExternoFormModal.vue'
import { confirm as confirmSwal } from '@/Utils/alertUtil.js'
import { useBreakpoints, breakpointsTailwind } from '@vueuse/core'
import { ESPERA_FILTROS_MS } from '@/Utils/filtroUtil'

const props = defineProps({
    vehiculosExternos: Object,
    filters: { type: Object, default: () => ({}) },
    flash: Object,
})

/* ------------------------------------------------------------------ */
/*  Buscador: placa o propietario (VehiculoExternoController::index)   */
/* ------------------------------------------------------------------ */
// Un enlace existente con ?nro_placa= se vuelca aquí para no perder el filtro.
const buscar = ref(props.filters?.buscar ?? props.filters?.nro_placa ?? '')
const hayBusqueda = computed(() => buscar.value.trim() !== '')

let debounceTimer = null
watch(buscar, (valor) => {
    clearTimeout(debounceTimer)
    debounceTimer = setTimeout(() => {
        router.get(
            route('vehiculos-externos.index'),
            { buscar: valor.trim() || undefined },
            { preserveState: true, replace: true },
        )
    }, ESPERA_FILTROS_MS)
})

// Debajo de "lg" (tablet en portrait y celular) se muestra un segundo
// listado en tarjetas con scroll infinito en vez de la tabla (ver
// .ai/rules/pages.md, "Listado responsivo con scroll infinito").
const breakpoints = useBreakpoints(breakpointsTailwind)
const isMobile = breakpoints.smaller('lg')

const modalRef = ref(null)

function abrirCrear() {
    modalRef.value?.open()
}

function abrirEditar(vehiculoExterno) {
    modalRef.value?.open(vehiculoExterno)
}

// El modal guarda por AJAX (para poder reutilizarse desde otros formularios
// sin navegar), así que aquí solo recargamos el listado con los datos frescos.
function recargarListado() {
    router.reload({ only: ['vehiculosExternos'], preserveScroll: true })
}

async function confirmDelete(vehiculoExterno) {
    const confirmado = await confirmSwal(
        `¿Eliminar el vehículo <strong>${vehiculoExterno.nro_placa}</strong>?`,
        'Eliminar Vehículo Externo',
        'Sí, eliminar',
    )

    if (!confirmado) {
        return
    }

    router.delete(route('vehiculos-externos.destroy', vehiculoExterno.id))
}
</script>

<template>
    <Head title="Vehículos Externos" />

    <!-- Page header -->
    <div class="d-flex align-items-center justify-content-between page-header-breadcrumb flex-wrap gap-2 mb-4">
        <div>
            <nav>
                <ol class="breadcrumb mb-1">
                    <li class="breadcrumb-item">
                        <Link :href="route('dashboard')">Inicio</Link>
                    </li>
                    <li class="breadcrumb-item active">Vehículos Externos</li>
                </ol>
            </nav>
            <h1 class="page-title fw-medium fs-18 mb-0">Vehículos Externos</h1>
        </div>
        <button v-can="'vehiculos-externos.crear'" type="button" class="btn btn-primary btn-wave" @click="abrirCrear">
            <i class="ri-add-line me-1"></i> Nuevo Vehículo Externo
        </button>
    </div>

    <!-- Flash messages -->
    <div v-if="flash?.success" class="alert alert-success alert-dismissible fade show" role="alert">
        <i class="ri-checkbox-circle-line me-2"></i>{{ flash.success }}
        <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
    </div>
    <div v-if="flash?.error" class="alert alert-danger alert-dismissible fade show" role="alert">
        <i class="ri-error-warning-line me-2"></i>{{ flash.error }}
        <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
    </div>

    <!-- Tabla -->
    <div class="card custom-card">
        <div class="card-header d-flex align-items-center justify-content-between flex-wrap gap-2">
            <div class="card-title">
                Listado
                <span class="badge bg-primary-transparent text-primary ms-2">
                    {{ vehiculosExternos.total }} registros
                </span>
            </div>
            <div class="input-group input-group-sm externos-buscador">
                <span class="input-group-text"><i class="ri-search-line" aria-hidden="true"></i></span>
                <input v-model="buscar" type="search" class="form-control" placeholder="Buscar por placa o propietario..."
                    aria-label="Buscar por placa o propietario" autocomplete="off" />
                <button v-if="hayBusqueda" type="button" class="btn btn-light" title="Borrar búsqueda"
                    aria-label="Borrar búsqueda" @click="buscar = ''">
                    <i class="ri-close-line" aria-hidden="true"></i>
                </button>
            </div>
        </div>
        <!-- Vista tabla: desktop -->
        <div v-if="!isMobile" class="card-body p-0">
            <div class="table-responsive">
                <table class="table table-hover mb-0">
                    <thead class="table-light">
                        <tr>
                            <th style="width:60px">#</th>
                            <th>Placa</th>
                            <th>Propietario</th>
                            <th style="width:150px" class="text-center">Acciones</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr v-if="vehiculosExternos.data.length === 0">
                            <td colspan="4" class="text-center py-5 text-muted">
                                <i class="ri-truck-line fs-3 d-block mb-2"></i>
                                {{ hayBusqueda ? 'Ningún vehículo externo coincide con la búsqueda.' : 'No se encontraron vehículos externos' }}
                            </td>
                        </tr>
                        <tr v-for="(vehiculoExterno, idx) in vehiculosExternos.data" :key="vehiculoExterno.id">
                            <td class="text-muted small">
                                {{ (vehiculosExternos.current_page - 1) * vehiculosExternos.per_page + idx + 1 }}
                            </td>
                            <td class="fw-medium">{{ vehiculoExterno.nro_placa }}</td>
                            <td>
                                <small class="text-muted">{{ vehiculoExterno.propietario || '—' }}</small>
                            </td>
                            <td class="text-center">
                                <div class="d-flex gap-1 justify-content-center">
                                    <button
                                        v-can="'vehiculos-externos.editar'"
                                        type="button"
                                        class="btn btn-sm btn-icon btn-info-light"
                                        title="Editar"
                                        @click="abrirEditar(vehiculoExterno)"
                                    >
                                        <i class="ri-edit-line"></i>
                                    </button>
                                    <button
                                        v-can="'vehiculos-externos.eliminar'"
                                        type="button"
                                        class="btn btn-sm btn-icon btn-danger-light"
                                        title="Eliminar"
                                        @click="confirmDelete(vehiculoExterno)"
                                    >
                                        <i class="ri-delete-bin-line"></i>
                                    </button>
                                </div>
                            </td>
                        </tr>
                    </tbody>
                </table>
            </div>
        </div>

        <!-- Vista tarjetas: tablet y celular, con scroll infinito -->
        <div v-else class="card-body p-2">
            <div v-if="vehiculosExternos.data.length === 0" class="text-center py-4 text-muted">
                <i class="ri-truck-line fs-3 d-block mb-2"></i>
                {{ hayBusqueda ? 'Ningún vehículo externo coincide con la búsqueda.' : 'No se encontraron vehículos externos' }}
            </div>

            <InfiniteScroll v-else data="vehiculosExternos" only-next as="div" class="d-flex flex-column gap-2">
                <div v-for="vehiculoExterno in vehiculosExternos.data" :key="vehiculoExterno.id" class="list-card-mobile border rounded-3 p-3">
                    <div class="d-flex align-items-center justify-content-between">
                        <div>
                            <span class="fw-medium d-block">{{ vehiculoExterno.nro_placa }}</span>
                            <small class="text-muted">{{ vehiculoExterno.propietario || '—' }}</small>
                        </div>
                        <div class="d-flex align-items-center gap-1">
                            <button v-can="'vehiculos-externos.editar'" type="button" class="btn btn-icon btn-info-light"
                                title="Editar" @click="abrirEditar(vehiculoExterno)">
                                <i class="ri-edit-line"></i>
                            </button>
                            <button v-can="'vehiculos-externos.eliminar'" type="button" class="btn btn-icon btn-danger-light"
                                title="Eliminar" @click="confirmDelete(vehiculoExterno)">
                                <i class="ri-delete-bin-line"></i>
                            </button>
                        </div>
                    </div>
                </div>

                <!-- Indicador de carga / fin de lista del scroll infinito -->
                <template #next="{ loading, hasMore }">
                    <div v-if="loading" class="text-center text-muted small py-2">
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        Cargando más vehículos...
                    </div>
                    <div v-else-if="!hasMore" class="text-center text-muted small py-2">
                        No hay más vehículos para mostrar.
                    </div>
                </template>
            </InfiniteScroll>
        </div>

        <!-- Paginador: sólo la tabla desktop. El listado mobile usa scroll
             infinito (InfiniteScroll arriba) en vez de páginas numeradas. -->
        <div v-if="!isMobile" class="card-footer d-flex align-items-center justify-content-between flex-wrap gap-2">
            <div class="text-muted small">
                Mostrando
                <strong>{{ vehiculosExternos.from ?? 0 }}</strong> -
                <strong>{{ vehiculosExternos.to ?? 0 }}</strong>
                de <strong>{{ vehiculosExternos.total }}</strong> resultados
            </div>
            <nav v-if="vehiculosExternos.last_page > 1" aria-label="Paginación">
                <ul class="pagination pagination-sm mb-0">
                    <li
                        v-for="link in vehiculosExternos.links"
                        :key="link.label"
                        class="page-item"
                        :class="{ active: link.active, disabled: !link.url }"
                    >
                        <Link
                            v-if="link.url"
                            :href="link.url"
                            class="page-link"
                            preserve-state
                            v-html="link.label"
                        />
                        <span v-else class="page-link" v-html="link.label" />
                    </li>
                </ul>
            </nav>
        </div>
    </div>

    <!-- Modal: crear / editar vehículo externo -->
    <VehiculoExternoFormModal ref="modalRef" @created="recargarListado" @updated="recargarListado" />
</template>
